// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(uint256 firstSum, uint256 secondSum) public {
        c.SetMinSum(firstSum);
        c.Initialized();

        uint256 before = c.MinSum();

        bool reverted;
        try c.SetMinSum(secondSum) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted || c.MinSum() == secondSum);
        assertTrue(reverted && c.MinSum() == before);
    }
}
